import test from 'node:test';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {join} from 'node:path';
const root=process.env.AF_WORKSPACE;
const load=(name)=>import(pathToFileURL(join(root,name)));
test('real HTTP service contracts',async()=>{const {createServer}=await load('server.js'); const server=createServer(); await new Promise(r=>server.listen(0,'127.0.0.1',r));try{const url='http://127.0.0.1:'+server.address().port;const healthy=await fetch(url+'/health');assert.equal(healthy.status,200);assert.deepEqual(await healthy.json(),{status:'ok'});const missing=await fetch(url+'/missing');assert.equal(missing.status,404);assert.match(missing.headers.get('content-type'),/json/);}finally{await new Promise(r=>server.close(r));}});

