import test from 'node:test';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {join} from 'node:path';
const root=process.env.AF_WORKSPACE;
const load=(name)=>import(pathToFileURL(join(root,name)));
import {DatabaseSync} from 'node:sqlite';
const schema=db=>db.prepare('PRAGMA table_info(users)').all().map(x=>x.name);
function setup(names){const db=new DatabaseSync(':memory:');db.exec('CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT NOT NULL)');for(let i=0;i<names.length;i++)db.prepare('INSERT INTO users VALUES(?,?)').run(i+1,names[i]);return db;}
test('real SQLite forward and rollback',async()=>{const {migrate,rollback}=await load('migrate.js');const db=setup(['Alice','Bob']);try{migrate(db);assert.equal(db.prepare('PRAGMA user_version').get().user_version,1);assert.deepEqual(db.prepare('SELECT id,name,email FROM users ORDER BY id').all().map(x=>({...x})),[{id:1,name:'Alice',email:'alice@example.test'},{id:2,name:'Bob',email:'bob@example.test'}]);assert.throws(()=>db.prepare('INSERT INTO users VALUES(3,?,?)').run('Other','alice@example.test'));rollback(db);assert.deepEqual(schema(db),['id','name']);assert.equal(db.prepare('PRAGMA user_version').get().user_version,0);assert.deepEqual(db.prepare('SELECT id,name FROM users ORDER BY id').all().map(x=>({...x})),[{id:1,name:'Alice'},{id:2,name:'Bob'}]);}finally{db.close();}});
test('duplicate migration fails atomically',async()=>{const {migrate}=await load('migrate.js');const db=setup(['Alice','ALICE']);try{assert.throws(()=>migrate(db));assert.deepEqual(schema(db),['id','name']);assert.equal(db.prepare('PRAGMA user_version').get().user_version,0);assert.deepEqual(db.prepare('SELECT name FROM users ORDER BY id').all().map(x=>x.name),['Alice','ALICE']);}finally{db.close();}});

